/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_products_after_insert` AFTER INSERT ON `tb_products` FOR EACH ROW BEGIN
    INSERT INTO tb_logs (
        table_name,
        operation,
        db_users,
        description,
        operation_date,
        operation_status
    )
    VALUES (
        'tb_products',
        'Create',
        USER(),
        CONCAT(
            'Producto creado (Rol Vendedor). ID=', NEW.ID,
            ', SKU=', NEW.SKU,
            ', Nombre=', NEW.name
        ),
        CURRENT_TIMESTAMP,
        b'1'
    );
END */;;
