CREATE TABLE `tbd_users_offer_products` (
  `product_offer_ID` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `user_ID` int(10) unsigned DEFAULT NULL,
  `product_ID` int(10) unsigned NOT NULL,
  `available_stock` int(10) unsigned NOT NULL DEFAULT '1',
  `status` bit(1) NOT NULL DEFAULT b'1',
  `creation_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `available_date` datetime DEFAULT NULL,
  `last_update` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`product_offer_ID`),
  KEY `fk_product_2_idx` (`product_ID`),
  KEY `fk_user_1_idx` (`user_ID`),
  CONSTRAINT `fk_product_2` FOREIGN KEY (`product_ID`) REFERENCES `tb_products` (`ID`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_user_1` FOREIGN KEY (`user_ID`) REFERENCES `tb_users` (`ID`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
